import {ChevronRightIcon} from '@sanity/icons/ChevronRight'
import {Fragment, useMemo} from 'react'
import {Text, Box, Flex, Icon} from 'ui5'

import {Tooltip} from '../../../ui-components/tooltip/Tooltip'

export interface CommentBreadcrumbsProps {
  titlePath: string[]
  maxLength: number
}

type Item = string | string[]

const separator = <Icon muted icon={ChevronRightIcon} style={{margin: '-0.4375rem'}} />

const renderItem = (item: string, index: number) => {
  return (
    <Box key={`${item}-${index}`} as="li">
      <Text truncate={1} size={1} weight="medium" as="div" trim={true}>
        {item}
      </Text>
    </Box>
  )
}

export function CommentBreadcrumbs(props: CommentBreadcrumbsProps) {
  const {titlePath, maxLength} = props

  const items: Item[] = useMemo(() => {
    const len = titlePath.length
    const beforeLength = Math.ceil(maxLength / 2)
    const afterLength = Math.floor(maxLength / 2)

    if (maxLength && len > maxLength) {
      return [
        ...titlePath.slice(0, beforeLength - 1),
        titlePath.slice(beforeLength - 1, len - afterLength),
        ...titlePath.slice(len - afterLength),
      ]
    }

    return titlePath
  }, [maxLength, titlePath])

  const nodes = useMemo(() => {
    return items.map((item, index) => {
      const key = `${item}-${index}`
      const showSeparator = index < items.length - 1

      if (Array.isArray(item)) {
        return (
          <Fragment key={key}>
            <Tooltip
              content={
                <Flex gap={2} padding={2} flexDirection="column">
                  {item.map(renderItem)}
                </Flex>
              }
            >
              <Box>{renderItem('...', index)}</Box>
            </Tooltip>

            {showSeparator && separator}
          </Fragment>
        )
      }

      return (
        <Fragment key={key}>
          {renderItem(item, index)}

          {showSeparator && separator}
        </Fragment>
      )
    })
  }, [items])

  return (
    <Flex alignItems="center" as="ol" gap={2}>
      {nodes}
    </Flex>
  )
}
